from .core import *
from fastcore.all import *
from importlib import resources
from io import BytesIO

import base64,PIL.Image

# %% ../nbs/01_capture.ipynb #4591f71d
_share_js = (resources.files('dialoghelper')/'screenshot.js').read_text()

async def start_share():
    "Ask the browser to share a screen or window, for `capture_screen`"
    await browser(_share_js + 'shareScreen()', wait=False)

# %% ../nbs/01_capture.ipynb #5c81465d
async def capture_screen(timeout=15):
    "Capture the shared screen as a PIL image."
    res = await browser(_share_js + 'done(await getScreenshot())', timeout=timeout)
    if not res: raise RuntimeError('No screen is being shared: call `start_share` first')
    return PIL.Image.open(BytesIO(base64.b64decode(res.split(',')[1])))

# %% ../nbs/01_capture.ipynb #c08b8ebc
@llmtool
async def capture_tool(timeout:int=15):
    "Capture the screen. Re-call this function to get the most recent screenshot, as needed. Use default timeout where possible"
    try: return await capture_screen(timeout)
    except Exception as e: return f'Capture failed: {e}'
